package chat.cloudlet.audit;
import android.app.*;import android.content.*;import android.os.*;import android.util.Base64;import android.view.accessibility.*;import org.json.*;import java.io.*;import java.lang.reflect.*;import java.util.*;
public final class QueueAudit extends Instrumentation {
 public void onCreate(Bundle args){super.onCreate(args);start();}
 private File journal;private Activity activity;private final ArrayList<String> checks=new ArrayList<>();
 private Object field(String name)throws Exception{Field f=activity.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(activity);}
 private void set(String name,Object value)throws Exception{Field f=activity.getClass().getDeclaredField(name);f.setAccessible(true);f.set(activity,value);}
 private JSONArray rows()throws Exception{if(!journal.exists())return new JSONArray();try(FileInputStream in=new FileInputStream(journal)){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return new JSONArray(out.toString("UTF-8"));}}
 private void awaitRows(int count)throws Exception{long end=System.currentTimeMillis()+15000;while(System.currentTimeMillis()<end){if(rows().length()==count)return;Thread.sleep(100);}throw new AssertionError("Export queue did not reach "+count+": "+rows());}
 private byte[] read(File file)throws Exception{try(FileInputStream in=new FileInputStream(file)){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return out.toByteArray();}}
 private String command(String value)throws Exception{try(ParcelFileDescriptor fd=getUiAutomation().executeShellCommand(value);FileInputStream in=new FileInputStream(fd.getFileDescriptor())){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return out.toString("UTF-8");}}
 private void ready()throws Exception{long end=System.currentTimeMillis()+30000;while(System.currentTimeMillis()<end){java.util.concurrent.CountDownLatch latch=new java.util.concurrent.CountDownLatch(1);boolean[] loaded={false};runOnMainSync(()->{try{((android.webkit.WebView)field("web")).evaluateJavascript("Boolean(document.querySelector('.home-screen'))",value->{loaded[0]="true".equals(value);latch.countDown();});}catch(Exception e){latch.countDown();}});if(latch.await(2,java.util.concurrent.TimeUnit.SECONDS)&&loaded[0])return;Thread.sleep(100);}throw new AssertionError("Actual local home did not become ready");}
 private void save()throws Exception{long end=System.currentTimeMillis()+15000;while(System.currentTimeMillis()<end){AccessibilityNodeInfo root=getUiAutomation().getRootInActiveWindow();if(root!=null){for(AccessibilityNodeInfo node:root.findAccessibilityNodeInfosByText("Save")){if("Save".equalsIgnoreCase(String.valueOf(node.getText()))&&node.isEnabled()){if(node.performAction(AccessibilityNodeInfo.ACTION_CLICK))return;}}}Thread.sleep(300);}throw new AssertionError("Native Save button not reachable");}
 public void onStart(){Bundle result=new Bundle();try{
  getUiAutomation();Intent intent=new Intent().setClassName("chat.cloudlet.phone","chat.cloudlet.phone.MainActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);activity=startActivitySync(intent);ready();journal=new File(getTargetContext().getCacheDir(),"pending-export.json");if(journal.exists())throw new AssertionError("Use an emulator without pending exports");
  Class<?> bridgeClass=Class.forName("chat.cloudlet.phone.MainActivity$Bridge",true,getTargetContext().getClassLoader());Constructor<?> constructor=bridgeClass.getDeclaredConstructors()[0];constructor.setAccessible(true);Object bridge=constructor.newInstance(activity);
  Method start=bridgeClass.getDeclaredMethod("startDownload",String.class,String.class,String.class),chunk=bridgeClass.getDeclaredMethod("downloadChunk",String.class,String.class),finish=bridgeClass.getDeclaredMethod("finishDownload",String.class);start.setAccessible(true);chunk.setAccessible(true);finish.setAccessible(true);
  String stamp=String.valueOf(System.currentTimeMillis());byte[][] expected=new byte[3][];
  for(int index=0;index<3;index++){expected[index]=new byte[4096*(index+1)];Arrays.fill(expected[index],(byte)(index+41));String id="audit-"+index,name="audit-"+stamp+"-"+index+".bin";if(!Boolean.TRUE.equals(start.invoke(bridge,id,name,"application/octet-stream"))||!Boolean.TRUE.equals(chunk.invoke(bridge,id,Base64.encodeToString(expected[index],Base64.NO_WRAP)))||!Boolean.TRUE.equals(finish.invoke(bridge,id)))throw new AssertionError("Native bridge rejected file");}
  awaitRows(3);JSONArray before=rows();for(int i=0;i<3;i++)if(!Arrays.equals(expected[i],read(new File(getTargetContext().getCacheDir(),before.getJSONObject(i).getString("file")))))throw new AssertionError("Queued source bytes changed");checks.add("Three real bridge exports retain all original bytes while first SAF picker is open");
  runOnMainSync(()->{try{((Map<?,?>)field("downloads")).clear();((Map<?,?>)field("downloadInfo")).clear();((Deque<?>)field("readyExports")).clear();set("exportId",null);set("exportFile",null);Method recover=activity.getClass().getDeclaredMethod("recoverExport");recover.setAccessible(true);recover.invoke(activity);}catch(Exception e){throw new RuntimeException(e);}});awaitRows(3);checks.add("Actual startup recovery reads all queued files from durable journal");
  for(int i=0;i<3;i++){Thread.sleep(600);save();awaitRows(2-i);String saved=command("base64 /sdcard/Download/audit-"+stamp+"-"+i+".bin");if(!Arrays.equals(expected[i],Base64.decode(saved,Base64.DEFAULT)))throw new AssertionError("SAF output bytes do not match "+i);}
  checks.add("Three real system Save operations produce exact files in Downloads and drain queue");
  Method error=activity.getClass().getDeclaredMethod("networkError",Exception.class);error.setAccessible(true);if(!new JSONObject((String)error.invoke(activity,new java.net.UnknownHostException())).getString("code").equals("dns"))throw new AssertionError("DNS classification");if(!new JSONObject((String)error.invoke(activity,new javax.net.ssl.SSLHandshakeException("secret URL"))).getString("message").equals("服务商的安全连接校验失败，请检查证书和设备时间。"))throw new AssertionError("TLS reason exposes underlying error");checks.add("Native DNS and TLS classification excludes sensitive exception text");
  result.putString("checks",new JSONArray(checks).toString());result.putString("result","passed");finish(Activity.RESULT_OK,result);
 }catch(Throwable error){result.putString("result","failed");result.putString("error",error.toString());finish(Activity.RESULT_CANCELED,result);}}
}
